if (first) {
	bne = NULL;
	i = &b->data->keys;

	if (btree_err_on((size_t)vstruct_bytes(b->data) > btree_buf_bytes(b),
			 -BCH_ERR_btree_node_read_err_must_retry,
			 c, ca, b, i, NULL,
			 bset_past_end_of_btree_node,
			 "btree node too big (u64s %u)",
			 le16_to_cpu(b->data->u64s)))
		goto fsck_err;
} else {
	bne = write_block(b);
	i = &bne->keys;

	if (btree_err_on((void *)vstruct_end(bne) > (void *)b->data + btree_buf_bytes(b),
			 -BCH_ERR_btree_node_read_err_must_retry,
			 c, ca, b, i, NULL,
			 bset_past_end_of_btree_node,
			 "btree node entry too big (u64s %u)",
			 le16_to_cpu(bne->keys.u64s)))
		goto fsck_err;

	if (i->seq != b->data->keys.seq)
		break;
}

